const items = $input.all();
const expandedItems = items.flatMap((item) => {
  const postalCodes = item?.json["Postal Code"].split(", ");
  return postalCodes.map((code) => ({
    json: {
      "Postal Code": code,
      "Send Body": item?.json["Send Body"],
    },
    pairedItem: items.indexOf(item),
  }));
});
return expandedItems;
